# Generated by GitHub Copilot - Oct-05-2026
def projection_records(rows, keys):
    """Keep observed IDs/times and a stable original-record index without full duplicates."""
    for index, row in enumerate(rows):
        yield {'source_record_index':index, **{key:row[key] for key in keys if key in row}}


# Generated by GitHub Copilot - Oct-05-2026
def write_indexed_projection(folder, name, records, source_artifact, max_records=500, max_bytes=2 * 1024 ** 2):
    """Write bounded deterministic chunks, each tied to the original source collection."""
    folder = Path(folder)
    refs, batch, batch_bytes, count = [], [], 0, 0

    def flush():
        """Atomically commit one small projection chunk and checksum its actual bytes."""
        nonlocal batch, batch_bytes
        if not batch:
            return
        path = folder / 'review_evidence' / f'{name}_{len(refs):05}.json'
        write_json(path, {'schema_version':'1.0','source_artifact':source_artifact,
                          'source_reference_scope':'original_analysis', 'records':batch})
        times = [value for row in batch for value in (row.get('start'),row.get('time'),row.get('end'))
                 if isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value)]
        refs.append({'path':path.relative_to(folder).as_posix(), 'record_count':len(batch),
                     'sha256':file_hash(path), 'start':min(times) if times else None,
                     'end':max(times) if times else None, 'bytes':path.stat().st_size})
        batch, batch_bytes = [], 0

    for record in records:
        size = len(json.dumps(sanitize_json_numbers(record), ensure_ascii=False, allow_nan=False, separators=(',',':')).encode('utf-8'))
        if batch and (len(batch) >= max_records or batch_bytes + size > max_bytes):
            flush()
        batch.append(record)
        batch_bytes += size
        count += 1
    flush()
    return {'format':'indexed_json_projection','schema_version':'1.0','source_artifact':source_artifact,
            'source_reference_scope':'original_analysis','record_count':count,'chunks':refs,
            'not_a_complete_raw_collection':True}


# Generated by GitHub Copilot - Oct-05-2026
def compact_analysis_document(analysis, folder):
    """Preserve cheap metadata and name explicit collections instead of embedding them."""
    folder = Path(folder)
    document = {key:value for key,value in analysis.items() if key not in COLLECTION_FILES}
    refs = {}
    for key, filename in COLLECTION_FILES.items():
        if key in analysis and (folder / filename).is_file():
            refs[key] = {'path':filename,'sha256':file_hash(folder / filename),
                         'record_count':len(analysis[key]) if isinstance(analysis[key],list) else None}
    document.update(schema_version='4.2', collection_storage='references', collection_refs=refs)
    for key, ref in refs.items():
        document[key + '_ref'] = ref
    return document


# Generated by GitHub Copilot - Oct-05-2026
def load_analysis_artifacts(folder, collections=None):
    """Hydrate trusted local artifact references; reject traversal, links and corruption."""
    folder = Path(folder).resolve()
    analysis = read_json(folder / 'analysis.json')
    if analysis.get('collection_storage') != 'references':
        return analysis
    allowed = set(collections) if collections is not None else set(COLLECTION_FILES)
    for key, ref in analysis.get('collection_refs', {}).items():
        if key not in allowed:
            continue
        if key not in COLLECTION_FILES or not isinstance(ref,dict) or ref.get('path') != COLLECTION_FILES[key]:
            raise ValueError('Referencia de colecao desconhecida ou insegura.')
        path = folder / ref['path']
        if path.is_symlink() or path.resolve().parent != folder or not path.is_file():
            raise ValueError('Referencia de artefato fora da pasta ou ausente.')
        if ref.get('sha256') != file_hash(path):
            raise ValueError('Checksum de artefato divergente; nao reutilizar evidencia corrompida.')
        analysis[key] = read_json(path)
    return analysis


