def create_compact_artifacts(analysis, folder, cfg=None):
    """Generate review-ready evidence without modifying the original benchmark inputs."""
    cfg = cfg or {}
    folder = Path(folder)
    chunks = int(cfg.get('chunk_records',500))
    maximum = int(cfg.get('chunk_max_bytes',2 * 1024 ** 2))
    observations = analysis.get('people_observations', [])
    observation_index = write_indexed_projection(folder,'people_observations', projection_records(observations,OBSERVATION_KEYS),
                                                 'people_observations.json',chunks,maximum)
    camera_index = write_indexed_projection(folder,'camera_timeline',projection_records(analysis.get('camera_timeline',[]),CAMERA_KEYS),
                                           'camera_timeline.json',chunks,maximum)
    master_index = write_indexed_projection(folder,'master_timeline',projection_records(analysis.get('master_timeline',[]),MASTER_KEYS),
                                           'master_timeline.json',chunks,maximum)
    motion_keys = ('time','center_x','center_y','velocity_x','velocity_y','source_camera_velocity_x','source_camera_velocity_y',
                   'residual_velocity_x','residual_velocity_y','confidence')
    motion_records = ({'person_id':person.get('person_id'),'source_person_index':person_index,'source_sample_index':sample_index,
                       **{key:sample[key] for key in motion_keys if key in sample}}
                      for person_index,person in enumerate(analysis.get('person_motion',[]))
                      for sample_index,sample in enumerate(person.get('samples',[])))
    motion_index = write_indexed_projection(folder,'person_motion',motion_records,'person_motion.json',chunks,maximum)
    frame_keys = ('time','frame','scene_id','visible_people','blur_laplacian_variance','brightness','source_camera_motion',
                  'sampling_fps','sampling_reasons','possible_black_frame')
    frame_index = write_indexed_projection(folder,'video_analysis',projection_records((analysis.get('video_analysis') or {}).get('frame_samples',[]),frame_keys),
                                          'video_analysis.json',chunks,maximum)
    manifest = analysis.get('run_manifest') or {}
    summary = {'schema_version':'4.2','producer_version':__version__,'metadata':analysis.get('metadata'),
               'execution_scope':analysis.get('execution_scope', 'full_pipeline'),
               'analysis_status':analysis.get('analysis_status'),'root_cause_stage':manifest.get('root_cause_stage'),
               'counts':{key:len(value) for key,value in analysis.items() if isinstance(value,list)},
               'analysis_quality':analysis.get('analysis_quality',{}),'qa_metrics':analysis.get('qa_metrics',{}),
               'semantic_metrics':analysis.get('semantic_metrics',{}),'candidate_metrics':analysis.get('candidate_metrics',{}),
               'stage_runtime':analysis.get('stage_runtime',{}),'stage_status':manifest.get('stage_status',analysis.get('stage_status',{})),
               'editorial_shortlist':analysis.get('editorial_shortlist',[]),
               'quality_gate':analysis.get('quality_gate',{}),
               'final_package_gate':analysis.get('final_package_gate'),
               'subtitle_review_metrics':analysis.get('subtitle_review_metrics'),
               'primary_editorial_theme':analysis.get('primary_editorial_theme'),
               'preview_status':(analysis.get('preview_validation') or {}).get('status','not_measured'),
               'warnings':analysis.get('issues',[]),'detailed_evidence':'review_evidence/'}
    people = {'schema_version':'1.0','layer_names':['tracklet','persistent_visual_identity','editorial_participant','acoustic_speaker'],
              'metrics':{key:value for key,value in analysis.get('analysis_quality',{}).items() if
                         any(term in key for term in ('track','person','reid','identity'))},
              'participants':analysis.get('participants',[]),
              'persistent_identity_count':len(analysis.get('person_identities',[])),
              'observation_projection':observation_index,'person_motion_projection':motion_index,
              'civil_identity_inferred':False}
    plan = analysis.get('camera_plan') or {}
    compact_plan = {key:plan.get(key) for key in ('schema_version','plan_id','profile','source_reference','selected_global_path',
                                                 'hard_constraints','transition_costs','metrics','planner_version')}
    compact_plan.update(compact_projection=True,source_artifact='camera_plan.json',source_reference_scope='original_analysis',
                        omitted_collections=['candidate_states','rejected_candidates'])
    compact_camera = {'schema_version':'1.0','director_timeline':analysis.get('camera_director_timeline',[]),
                      'legacy_camera_projection':camera_index,'camera_metrics':{key:value for key,value in analysis.get('analysis_quality',{}).items()
                      if any(term in key for term in ('coverage','focus','camera','switch','preservation'))}}
    compact_master = {'schema_version':'1.0','master_timeline_projection':master_index,'text_resolves_via':'transcript_segments.json'}
    handoff = {'schema_version':'4.2','producer_version':__version__,'metadata_locale':'pt-BR',
               'analysis_summary':summary,'second_curation_package_ref':{'path':'second_curation_package.json'},
               'transcript_refs':{'segments':'transcript_segments.json','words':'words.json','low_confidence':'low_confidence_words.json'},
               'participants_ref':'participants.json','speakers_ref':'speakers.json','person_identities_ref':'person_identities.json',
               'qa_refs':{'questions':'question_candidates.json','answer_pairs':'question_answer_pairs.json'},
               'topics_ref':'topics.json','program_sections_ref':'program_sections.json','story_arcs_ref':'story_arcs.json',
               'main_moments_ref':'main_moments.json','people_summary_ref':'people_summary.json',
               'camera_plan_ref':'camera_plan.compact.json','camera_timeline_ref':'camera_timeline.compact.json',
               'master_timeline_ref':'master_timeline.compact.json','video_frame_projection':frame_index,
               'all_data_untrusted':True,'final_second_curation_not_performed':True}
    artifacts = {'analysis_summary.json':summary,'people_summary.json':people,'camera_plan.compact.json':compact_plan,
                 'camera_timeline.compact.json':compact_camera,'master_timeline.compact.json':compact_master,
                 'CHATGPT_ANALYSIS_HANDOFF.compact.json':handoff}
    for filename,payload in artifacts.items():
        write_json(folder / filename,payload)
    paths = [folder / filename for filename in artifacts]
    for index in (observation_index,camera_index,master_index,motion_index,frame_index):
        paths.extend(folder / chunk['path'] for chunk in index['chunks'])
    return paths
